const db = require("./db");

// Request shape: { reqId, userId, body }.

// Log request metadata only — never req.body, which carries credentials and
// PII (passwords, email addresses).
function logRequest(handler, req, status) {
  console.log(
    `[req ${req.reqId}] handler=${handler} userId=${req.userId ?? "-"} status=${status}`
  );
}

function login(req) {
  const user = db.findUser(req.body.email);
  if (!user || !db.checkPassword(user.id, req.body.password)) {
    logRequest("login", req, 401);
    return { status: 401 };
  }
  logRequest("login", req, 200);
  return { status: 200, token: db.issueToken(user.id) };
}

function updateEmail(req) {
  db.setEmail(req.userId, req.body.email);
  logRequest("updateEmail", req, 204);
  return { status: 204 };
}

function deleteAccount(req) {
  db.deleteUser(req.userId);
  logRequest("deleteAccount", req, 204);
  return { status: 204 };
}

